"""Campaign-local validation; native Dynamical references, not a second registry."""

from __future__ import annotations

import hashlib
import json
from typing import Any

from dynamical.campaign import EvidenceClass, EvidenceReference
from dynamical.schema import ProspectiveRef


class ContractError(ValueError):
    """A request cannot be represented truthfully under this campaign contract."""


class ConflictError(ContractError):
    """An immutable identifier was reused for different content."""


# Historical fits remain inspectable. Their audit found domain, evidence-transfer
# and uncertainty defects; they cannot supply NEW physical numerical forecasts.
# This targeted quarantine is not certification of every other model.
AUDITED_UNSAFE_PHYSICAL_FITS = frozenset({
    # v10's first maintained export predates required physical sampling-plan matching.
    "0e7c9cf66c686bc47c9677601b2669c3602655df3b40edb830eeb82f18bb461a",
    # Interim v10 export predates required physical porosity sampling/weighting.
    "d5d589dc16d73362df1367fcbd6c571a2f31155cb709e4d9bec9fdfc9f4c05ac",
    "1e29ad439dc2d7f2f7c7eecd282712cafc55785a58750c7adfc783b3460a5e31",
    "1a8ec4d9ea277449caf439ed01a04e2d069583b9a18eedd5daadc29d702c0ff6",
    "89a39018ae6e17fff529e094852e034b956c34311ddc64e55bfece23015fb721",
    "8bb4374635daee261f08cce062d1e97e5dfbe528c496b2ba93bd23b30783034d",
    "5fa1b4065eb090a2a2287a95ff59ebf10c811b998340b1f4a5cfbeabfc11cc11",
})


def check_physical_forecast_source(source_sha256, request, prediction):
    if request.get("origin") != "physical" or source_sha256 not in AUDITED_UNSAFE_PHYSICAL_FITS:
        return
    def numerical(value):
        if isinstance(value, dict):
            return (type(value.get("mean")) in (int, float)
                    or any(numerical(v) for v in value.values()))
        return isinstance(value, list) and any(numerical(v) for v in value)
    if numerical(prediction):
        raise ContractError("Audited fitted source is quarantined for physical numerical forecasts; "
                            "adopt a corrected version or record an explicit abstention. "
                            "See docs/FITTED_MODELS.md and ASTRA_V8_REVIEW.md")


def canonical(value: Any) -> str:
    try:
        return json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False)
    except (ValueError, TypeError) as exc:
        raise ContractError("records must contain finite JSON values") from exc


def digest(value: Any) -> str:
    return hashlib.sha256(canonical(value).encode()).hexdigest()


def require_id(value: Any, field: str) -> str:
    if not isinstance(value, str) or not value.strip() or len(value) > 256:
        raise ContractError(f"{field} must be a nonempty identifier (at most 256 characters)")
    return value


def request_record(request: dict) -> dict:
    """Validate stable material sampling units, retaining scientific extension fields."""
    if not isinstance(request, dict):
        raise ContractError("request must be an object with top-level lot_id, origin and specimens")
    canonical(request)
    require_id(request.get("lot_id"), "request.lot_id (top level; specimen lot_id does not replace it)")
    if not isinstance(request.get("origin"), str) or request["origin"] not in {"synthetic", "physical"}:
        raise ContractError("request.origin must be explicit at the top level: synthetic or physical; "
                            "put process descriptions in separate extension fields")
    operation = request.get("operation", "manufacture")
    if not isinstance(operation, str) or operation not in {"manufacture", "anneal", "measure"}:
        raise ContractError("request.operation must be manufacture, anneal or measure")
    if operation != "manufacture":
        for key in ("input_stage", "output_stage"):
            require_id(request.get(key), key)
        if operation == "measure" and request["input_stage"] != request["output_stage"]:
            raise ContractError("measurement cannot change the processing stage")
        if operation == "anneal" and request["input_stage"] == request["output_stage"]:
            raise ContractError("annealing requires a distinct output stage")
    specimens = request.get("specimens")
    if not isinstance(specimens, list) or not specimens:
        raise ContractError("a batch requires at least one independently identified specimen")
    ids = []
    cycles = {}
    for specimen in specimens:
        if not isinstance(specimen, dict):
            raise ContractError("specimens must be objects")
        for key in ("specimen_id", "preparation_id", "cycle_id"):
            require_id(specimen.get(key), key)
        if not isinstance(specimen.get("conditions"), dict):
            raise ContractError("each specimen requires a conditions object")
        if specimen.get("treatment_cycle_id") is not None:
            require_id(specimen["treatment_cycle_id"], "treatment_cycle_id")
        # Existing-body measurements keep their manufacturing cycle identity but
        # can request different fields or assays. Anneal cycles have a separate ID.
        cycle_id = (specimen["cycle_id"] if operation == "manufacture" else
                    specimen.get("treatment_cycle_id", specimen["specimen_id"])
                    if operation == "anneal" else specimen["specimen_id"])
        previous = cycles.get(cycle_id)
        before = previous["conditions"] if previous is not None else None
        after = specimen["conditions"]
        if operation == "anneal":
            # Bodies in one furnace cycle can have different masses, geometry or
            # microscopy selections. Those do not imply different heat treatments.
            specimen_fields = {"mass_g", "remaining_mass_g", "diameter_mm", "height_mm",
                               "thickness_mm", "measurement_context", "sampling_plan",
                               "section_id", "field_id"}
            before = ({k: v for k, v in before.items() if k not in specimen_fields}
                      if before is not None else None)
            after = {k: v for k, v in after.items() if k not in specimen_fields}
        if previous is not None and canonical(before) != canonical(after):
            changed = sorted(k for k in set(before) | set(after)
                             if k not in before or k not in after
                             or canonical(before[k]) != canonical(after[k]))
            raise ConflictError(
                f"conflicting cycle {cycle_id!r} within this request: specimens "
                f"{previous['specimen_id']!r} and {specimen['specimen_id']!r} have different "
                f"conditions ({', '.join(changed)}). A cycle identifies one processing execution; "
                "use distinct cycle IDs for separate executions. No request was committed."
            )
        cycles[cycle_id] = specimen
        ids.append(specimen["specimen_id"])
    if len(ids) != len(set(ids)):
        raise ContractError("specimen IDs must be unique within a batch")
    preparations = request.get("preparations", [])
    if not isinstance(preparations, list):
        raise ContractError("preparations must be a list")
    preparation_ids = []
    for preparation in preparations:
        if not isinstance(preparation, dict):
            raise ContractError("preparations must be objects")
        preparation_ids.append(require_id(preparation.get("preparation_id"), "preparation_id"))
        if preparation.get("lot_id") != request["lot_id"]:
            raise ContractError("preparation must identify the declared lot")
        if not isinstance(preparation.get("conditions"), dict):
            raise ContractError("preparation requires explicit planned conditions")
    if len(preparation_ids) != len(set(preparation_ids)):
        raise ContractError("preparation IDs must be unique")
    if not set(preparation_ids) <= {s["preparation_id"] for s in specimens}:
        raise ContractError("preparations must be used by a declared specimen")
    sample_ids = []
    for sample in request.get("samples", []):
        require_id(sample.get("sample_id"), "sample_id")
        if sample.get("sample_kind") != "powder_aliquot":
            raise ContractError("inventory samples currently support powder_aliquot only")
        if (
            sample.get("lot_id") != request["lot_id"]
            or sample.get("parent_id") != request["lot_id"]
        ):
            raise ContractError("powder aliquot must link to the declared lot")
        sample_ids.append(sample["sample_id"])
    if len(sample_ids) != len(set(sample_ids)) or set(ids) & set(sample_ids):
        raise ContractError("sampling unit identifiers must be unique")
    return json.loads(canonical(request))


def delivered_values(requested: dict, delivered: dict | None) -> dict:
    """Retain explicit readbacks, recursively marking unknown requested settings null."""
    if delivered is None:
        delivered = {}
    if not isinstance(delivered, dict):
        raise ContractError("delivered conditions must be objects or null")
    result = dict(delivered)
    for key, value in requested.items():
        if isinstance(value, dict):
            result[key] = delivered_values(value, delivered.get(key))
        elif key not in delivered:
            result[key] = None
    return result


def prospective_ref(record: dict) -> dict:
    return ProspectiveRef(
        sha256=digest(record), label="frozen batch forecast and evidence cutoff", path=None
    ).model_dump(mode="json")


def observation_unit(observation: dict) -> dict:
    """Normalize spelling only, never silently convert measured magnitudes."""
    quantity = observation.get("quantity")
    unit = observation.get("unit")
    aliases = {
        "density_g_cm3": {"g/cm3": "g/cm^3", "g/cm³": "g/cm^3", "g/cm^3": "g/cm^3"},
        "grain_size_nm": {"nm": "nm"},
        "grain_d90_nm": {"nm": "nm"},
        "coarse_number_fraction": {"1": "1"},
        "porosity_area_fraction": {"1": "1"},
    }
    if quantity not in aliases:
        return dict(observation)
    if unit not in aliases[quantity]:
        raise ContractError(
            f"unsupported unit {unit!r} for {quantity}; explicitly convert with provenance"
        )
    result = dict(observation)
    normalized = aliases[quantity][unit]
    if unit != normalized:
        result["reported_unit"] = unit
        result["unit"] = normalized
        result["unit_normalization"] = "spelling_alias_no_numeric_conversion"
    return result


def evidence_ref(evidence_id: str, sha256: str, origin: str, media_type: str) -> dict:
    # Physical identifies the reported source, not facility authority or calibration.
    return EvidenceReference(
        evidence_id=evidence_id,
        uri=f"urn:sha256:{sha256}",
        sha256=sha256,
        media_type=media_type,
        role="operator-delivered-raw-artifact",
        provider_id="ndfeb-sps-operator-import" if origin == "physical" else "ndfeb-sps-simulator",
        evidence_class=EvidenceClass.PHYSICAL if origin == "physical" else EvidenceClass.SIMULATOR,
    ).to_dict()
